<?php if(!$income['items']): empty_state(); else: ?><div class="table-wrap"><table class="data-table income-table"><thead><tr><th><?= t('Order / work') ?></th><?php if($adminIncome): ?><th><?= t('Author') ?></th><?php endif ?><th><?= t('Gross / net revenue') ?></th><th><?= t('Author share') ?></th><th><?= t('Status / release date') ?></th></tr></thead><tbody><?php foreach($income['items'] as $row): ?><tr><td class="table-title"><strong><?= e($row['title']) ?></strong><small><?= e($row['order_no']) ?></small></td><?php if($adminIncome): ?><td><a href="<?= e(au('edit_user',['id'=>$row['author_id']])) ?>"><?= e($row['display_name']) ?></a><small>#<?= (int)$row['author_id'] ?></small></td><?php endif ?><td><?= e(price((int)$row['gross_amount'],'balance')) ?><small><?= e(price((int)$row['net_amount'],'balance')) ?></small></td><td><strong><?= e(price((int)$row['share_amount'],'earnings')) ?></strong><small><?= number_format((int)$row['share_bps']/100,2) ?>%</small></td><td><span class="pill <?= e($row['status']) ?>"><?= t($row['status']) ?></span><small><?= dt((int)$row['release_at']) ?></small><?php if($row['order_status']==='refund_requested'): ?><small><?= t('Refund dispute pauses settlement') ?></small><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
